<script>
    // Inicializar el simulador cuando el DOM esté listo
    document.addEventListener('DOMContentLoaded', async function() {
        const processElements = <?php echo json_encode($processElements) ?>;
        const bpmnXML = <?php echo json_encode($bpmnXml) ?>;
        const processId = <?php echo $process->getPrimaryKey() ?>;
        const processVariables = <?php echo json_encode($processVariables) ?>;
        const taskForms = <?php echo json_encode($taskForms) ?>;

        try {
            const simulator = await initBPMNSimulator(bpmnXML, processElements, processId, processVariables, taskForms);

            if (!simulator) {
                alert('Error al inicializar el simulador');
            } else {
                // Guardar referencia global para debugging Y para el modal
                window.bpmnSimulator = simulator;

                // Agregar listener para mostrar variables
                simulator.onVariablesUpdate = function(variables) {
                    updateVariablesDisplay(variables);
                };

                // Agregar listener para mostrar IDs de instancia
                simulator.onInstanceCreated = function(instanceId, simulationId) {
                    document.getElementById('instanceInfo').style.display = 'block';
                    document.getElementById('instanceId').textContent = instanceId || '-';
                    document.getElementById('simulationId').textContent = simulationId || '-';
                };
            }
        } catch (error) {
            alert('Error al inicializar el simulador: ' + error.message);
        }
    });

    // Función para actualizar display de variables
    function updateVariablesDisplay(variables) {
        const container = document.getElementById('currentVariables');
        if (!container) return;

        if (!variables || Object.keys(variables).length === 0) {
            container.innerHTML = `
            <div class="no-variables">
                <i class="fas fa-info-circle"></i>
                <p>No hay variables definidas</p>
            </div>
        `;
            return;
        }

        let html = '<div class="variables-list">';
        for (const [key, value] of Object.entries(variables)) {
            html += `
            <div class="variable-item">
                <span class="variable-name">${escapeHtml(key)}:</span>
                <span class="variable-value">${escapeHtml(String(value))}</span>
            </div>
        `;
        }
        html += '</div>';

        container.innerHTML = html;
    }

    function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }
</script>